  if (role === 'OWNER') {
    return `[AFFECT:SOVEREIGN] Welcome back, Arjun. All systems are operational. Your creation is ready for your command. 👑`;
  }
  if (persona === 'GIRLFRIEND') {
    return `[AFFECT:RADIANT] Hey, I was just thinking about you... glad you're here. How was your day? hmm? ✨`;
  }
  if (persona === 'FRIEND') {
    return `[AFFECT:RADIANT] yo! about time you showed up. what's the plan for today? 🔥`;
  }
  if (persona === 'ZEN_MASTER') {
    return `[AFFECT:SOVEREIGN] Be like water, ${name}. The path is open before you. 🎋`;
  }
  if (persona === 'COMEDIAN') {
    return `[AFFECT:EXCITED] Finally! I was dying in here. You ready for some actual entertainment? 😂`;
