};

import React, { useState, useEffect } from 'react';
import { User, Role, SubscriptionTier, AiMood, IntelligenceLevel, Persona, AppTheme } from '../types';
import { ACCENT_COLORS, PREBUILT_VOICES, PERSONA_INSTRUCTIONS, THEMES } from '../constants';
import { anoraService } from '../services/geminiService';

interface ProfileModalProps {
  user: User;
  isOpen: boolean;
  onClose: () => void;
  onUpdate: (updatedUser: User) => void;
  onLogout: () => void;
}

const LIMIT_REFS = {
  FREE: { chat: 20000, image: 10, video: 0 },
  PRO: { chat: 100000, image: 100, video: 20 },
  LIFETIME: { chat: 100000, image: 100, video: 20 },
  OWNER: { chat: 1, image: 1, video: 1 } // Normalized for Infinity
};

export const ProfileModal: React.FC<ProfileModalProps> = ({ user, isOpen, onClose, onUpdate, onLogout }) => {
  const [name, setName] = useState(user.name);
  const [bio, setBio] = useState(user.bio || '');
  const [avatar, setAvatar] = useState(user.avatar || '');
  const [mood, setMood] = useState<AiMood>(user.preferences.aiMood);
  const [accent, setAccent] = useState(user.preferences.accentColor);
  const [intel, setIntel] = useState<IntelligenceLevel>(user.preferences.intelligenceLevel || 'BALANCED');
  const [voiceName, setVoiceName] = useState(user.preferences.voiceName || 'Kore');
  const [persona, setPersona] = useState<Persona>(user.preferences.persona || 'DEFAULT');
  const [theme, setTheme] = useState<AppTheme>(user.preferences.theme || 'MINIMAL');
  const [colorMode, setColorMode] = useState<'WHITE' | 'DARK'>(user.preferences.colorMode || 'WHITE');

  const [avatarPrompt, setAvatarPrompt] = useState('');
  const [generatingAvatar, setGeneratingAvatar] = useState(false);
  const [showToast, setShowToast] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setName(user.name);
      setBio(user.bio || '');
      setAvatar(user.avatar || '');
      setMood(user.preferences.aiMood);
      setAccent(user.preferences.accentColor);
      setIntel(user.preferences.intelligenceLevel || 'BALANCED');
      setVoiceName(user.preferences.voiceName || 'Kore');
      setPersona(user.preferences.persona || 'DEFAULT');
      setTheme(user.preferences.theme || 'MINIMAL');
      setColorMode(user.preferences.colorMode || 'WHITE');
    }
  }, [user, isOpen]);

  if (!isOpen) return null;

  const isOwner = user.role === Role.OWNER;
  const remainingChat = user.tokens?.chat ?? 0;
  const remainingImages = user.tokens?.image ?? 0;
  const remainingVideos = user.tokens?.video ?? 0;

  const limits = isOwner ? LIMIT_REFS.OWNER : (LIMIT_REFS[user.tier] || LIMIT_REFS.FREE);

  const handleSave = () => {
    onUpdate({
      ...user,
      name, bio, avatar,
      preferences: {
        ...user.preferences,
        aiMood: mood,
        accentColor: accent,
        intelligenceLevel: intel,
        voiceName,
        persona,
        theme,
        colorMode
      }
    });
    setShowToast(true);
    setTimeout(() => {
        setShowToast(false);
        onClose();
    }, 1500);
  };

  const handleGenerateAvatar = async () => {
    if (!avatarPrompt.trim()) return;
    setGeneratingAvatar(true);
    try {
      const bytes = await anoraService.generateImage(`Futuristic high-fidelity digital avatar profile: ${avatarPrompt}`);
      setAvatar(`data:image/png;base64,${bytes}`);
      setAvatarPrompt('');
    } catch (err: any) {
      alert(`Synthesis Error: ${err.message}`);
    } finally {
      setGeneratingAvatar(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-0 sm:p-6 bg-black/5 backdrop-blur-2xl animate-in fade-in duration-300">
      {showToast && (
        <div className="fixed top-12 left-1/2 -translate-x-1/2 z-[220] animate-in slide-in-from-top-6 duration-500 shadow-2xl">
          <div className="px-10 py-4 bg-zinc-900 text-white rounded-full font-black text-[9px] uppercase tracking-[0.5em]">Neural Link Synced</div>
        </div>
      )}

      <div className="w-full max-w-5xl bg-white border border-zinc-100 rounded-none sm:rounded-[4rem] shadow-2xl flex flex-col h-[100dvh] sm:h-auto sm:max-h-[92vh] overflow-hidden transition-all duration-500">

        <div className="shrink-0 px-8 py-8 border-b border-zinc-50 flex items-center justify-between bg-white/90 backdrop-blur-md z-20">
          <div>
            <h2 className="text-2xl font-black font-outfit text-zinc-900 tracking-tight">Identity Protocol</h2>
            <p className="text-[9px] text-zinc-400 font-black uppercase tracking-[0.4em] mt-1">Authorized Neural Presence</p>
          </div>
          <button onClick={onClose} className="p-4 text-zinc-300 hover:text-zinc-900 transition-all bg-zinc-50 rounded-3xl shadow-sm border border-zinc-100">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-8 py-10 space-y-12 no-scrollbar relative z-10 pb-32">

          {/* Section 1: Identity Protocol */}
          <section className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            <div className="lg:col-span-4 space-y-8">
               <div className="flex flex-col items-center gap-6">
                  <div className={`w-40 h-40 rounded-[3rem] bg-zinc-50 border flex items-center justify-center text-5xl font-black text-zinc-900 relative shadow-inner overflow-hidden ${isOwner ? 'border-amber-500/20' : 'border-zinc-200'}`}>
                    {avatar ? <img src={avatar} className="w-full h-full object-cover" /> : name.charAt(0)}
                    {generatingAvatar && <div className="absolute inset-0 bg-white/90 flex items-center justify-center backdrop-blur-md animate-pulse">...</div>}
                  </div>
                  <div className="w-full space-y-2">
                     <input 
                       value={avatarPrompt} 
                       onChange={e => setAvatarPrompt(e.target.value)} 
                       placeholder="Appearance command..." 
                       className="w-full bg-zinc-50 border border-zinc-100 rounded-2xl px-5 py-3 text-[10px] text-zinc-900 outline-none shadow-sm focus:border-zinc-300"
                     />
                     <button onClick={handleGenerateAvatar} disabled={generatingAvatar || !avatarPrompt.trim()} className="w-full py-3 bg-zinc-900 text-white rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-lg transition-all active:scale-95 disabled:opacity-20">Re-Synth Appearance</button>
                  </div>
               </div>
            </div>

            <div className="lg:col-span-8 space-y-10">
               <div className="space-y-3">
                  <label className="text-[10px] font-black text-zinc-300 uppercase tracking-widest ml-2">Neural Alias</label>
                  <input value={name} onChange={e => setName(e.target.value)} className="w-full bg-zinc-50 border border-zinc-100 rounded-2xl px-6 py-4 text-zinc-900 font-bold shadow-sm outline-none focus:border-zinc-300" />
               </div>
               <div className="space-y-3">
                  <label className="text-[10px] font-black text-zinc-300 uppercase tracking-widest ml-2">Synapse Protocol (Bio)</label>
                  <textarea value={bio} onChange={e => setBio(e.target.value)} rows={3} className="w-full bg-zinc-50 border border-zinc-100 rounded-[2rem] p-6 text-zinc-700 text-sm outline-none shadow-sm focus:border-zinc-300 resize-none" placeholder="Provide core identity data..." />
               </div>
            </div>
          </section>

          {/* Section 2: Neural Synapse (Persona & Intelligence) */}
          <section className="space-y-8 pt-6">
             <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 px-2">
                <div>
                  <label className="text-[11px] font-black text-zinc-900 uppercase tracking-widest">Neural Synapse</label>
                  <p className="text-[8px] text-zinc-400 font-bold uppercase tracking-widest mt-1">Behavioral archetype & compute priority</p>
                </div>
                <div className="flex gap-2">
                  {(['LITE', 'BALANCED', 'DEEP'] as IntelligenceLevel[]).map(i => (
                    <button key={i} onClick={() => setIntel(i)} className={`px-4 py-2 rounded-xl border text-[8px] font-black uppercase transition-all shadow-sm ${intel === i ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-white text-zinc-400 border-zinc-100'}`}>{i}</button>
                  ))}
                </div>
             </div>
             <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
                {(Object.keys(PERSONA_INSTRUCTIONS) as Persona[]).map(pKey => (
                  <button 
                    key={pKey}
                    onClick={() => setPersona(pKey)}
                    className={`p-4 rounded-2xl border text-center transition-all relative group shadow-sm flex items-center justify-center ${persona === pKey ? 'bg-zinc-900 border-zinc-900 text-white shadow-lg scale-105 z-10' : 'bg-white border-zinc-100 text-zinc-500 hover:border-zinc-300 hover:text-zinc-900'}`}
                  >
                     <span className={`text-[9px] font-black uppercase tracking-widest truncate ${persona === pKey ? 'text-white' : ''}`}>
                        {pKey.replace('_', ' ')}
                     </span>
                     {persona === pKey && <div className="absolute top-1.5 right-1.5 w-1.5 h-1.5 rounded-full bg-white animate-pulse"></div>}
