};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('anora_session');
    return saved ? JSON.parse(saved) : null;
  });

  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isThinking, setIsThinking] = useState(false);
  const [activeAffect, setActiveAffect] = useState<NeuralAffect>('SOVEREIGN');
  const [isVoiceMode, setIsVoiceMode] = useState(false);
  const [isCommandCenterOpen, setIsCommandCenterOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isHubOpen, setIsHubOpen] = useState(false);
  const [pendingImages, setPendingImages] = useState<string[]>([]);
  const [speakingId, setSpeakingId] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const activeSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const currentVocalizeIdRef = useRef<string | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    const handleDbUpdate = () => {
      if (!currentUser) return;
      const users: User[] = JSON.parse(localStorage.getItem('anora_users_db') || '[]');
      const updated = users.find(u => u.id === currentUser.id);
      if (updated && (updated.tier !== currentUser.tier || updated.role !== currentUser.role)) {
        setCurrentUser(updated);
      }
    };
    window.addEventListener('anora_database_updated', handleDbUpdate);
    return () => window.removeEventListener('anora_database_updated', handleDbUpdate);
  }, [currentUser]);

  useEffect(() => {
    if (currentUser) {
      const today = new Date().toDateString();
      if (!currentUser.tokens || currentUser.tokens.lastReset !== today) {
        const limits = currentUser.role === Role.OWNER ? TOKEN_LIMITS.OWNER : (TOKEN_LIMITS[currentUser.tier] || TOKEN_LIMITS.FREE);
        const resetUser = {
          ...currentUser,
          tokens: { ...limits, lastReset: today }
        };
        setCurrentUser(resetUser);
        return; 
      }

      localStorage.setItem('anora_session', JSON.stringify(currentUser));
      const savedDb = localStorage.getItem('anora_users_db');
      const users: User[] = savedDb ? JSON.parse(savedDb) : [];
      const exists = users.find(u => u.id === currentUser.id);
      const updatedUsers = exists ? users.map((u: User) => u.id === currentUser.id ? currentUser : u) : [...users, currentUser];
      localStorage.setItem('anora_users_db', JSON.stringify(updatedUsers));
      anoraService.initChat(currentUser);
    }
  }, [currentUser]);

  // PERSONA-BASED HISTORY LOADING
  useEffect(() => {
    if (currentUser) {
      const persona = currentUser.preferences.persona || 'DEFAULT';
      const historyKey = `anora_history_${currentUser.email}_${persona}`;

      // Migration from old single-history logic
      const legacyKey = `anora_history_${currentUser.email}`;
      const legacyHistory = localStorage.getItem(legacyKey);

      const savedHistory = localStorage.getItem(historyKey);

      if (savedHistory) {
        try { setMessages(JSON.parse(savedHistory)); } catch (e) { handleNewThread(); }
      } else if (legacyHistory && persona === 'DEFAULT') {
        // Carry over old history to DEFAULT persona
        try { 
          const h = JSON.parse(legacyHistory);
          setMessages(h);
          localStorage.setItem(historyKey, legacyHistory);
          localStorage.removeItem(legacyKey);
        } catch (e) { handleNewThread(); }
      } else {
        handleNewThread();
      }
    }
  }, [currentUser?.email, currentUser?.preferences.persona]);

  // PERSONA-BASED HISTORY PERSISTENCE
  useEffect(() => {
    if (currentUser && messages.length > 0) {
      const persona = currentUser.preferences.persona || 'DEFAULT';
      const historyKey = `anora_history_${currentUser.email}_${persona}`;
      try {
        localStorage.setItem(historyKey, JSON.stringify(messages));
      } catch (e) {
        try { localStorage.setItem(historyKey, JSON.stringify(messages.slice(-20))); } catch (e2) {}
      }

      const lastAnora = [...messages].reverse().find(m => m.role === 'anora');
      if (lastAnora?.affect) setActiveAffect(lastAnora.affect);
    }
  }, [messages, currentUser?.email, currentUser?.preferences.persona]);

  const deductTokens = useCallback((type: keyof Omit<TokenUsage, 'lastReset'>, amount: number) => {
    if (!currentUser) return false;
    if (currentUser.role === Role.OWNER) return true;

    const tokens = currentUser.tokens || { chat: 0, image: 0, video: 0, audio: 0, lastReset: '' };
    if (tokens[type] < amount) {
      alert(`Neural Resources Exhausted: ${type.toUpperCase()} pool empty for today.`);
      return false;
    }

    const updatedUser = {
      ...currentUser,
      tokens: { ...tokens, [type]: tokens[type] - amount }
    };
    setCurrentUser(updatedUser);
    return true;
  }, [currentUser]);

  const handleNewThread = () => {
    if (!currentUser) return;
    const initialRaw = INITIAL_MESSAGE(currentUser.name, currentUser.role, currentUser.preferences.persona || 'DEFAULT');
    const { content, affect } = anoraService.parseAffect(initialRaw);
    const initial: Message = { id: 'init_' + Date.now(), role: 'anora', content, affect, timestamp: new Date() };
    setMessages([initial]);

    const persona = currentUser.preferences.persona || 'DEFAULT';
    localStorage.setItem(`anora_history_${currentUser.email}_${persona}`, JSON.stringify([initial]));
    anoraService.initChat(currentUser);
  };

  const handleLogout = useCallback(() => {
    setCurrentUser(null);
    localStorage.removeItem('anora_session');
    setMessages([]);
  }, []);

  const handleSaveToMemory = useCallback((content: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, memory: [...(currentUser.memory || []), { id: `mem_${Date.now()}`, content, category: 'PERSONAL', timestamp: new Date().toISOString(), strength: 5 }] });
  }, [currentUser]);

  const handleSaveToReminders = useCallback((content: string) => {
    if (!currentUser) return;
    setCurrentUser({ ...currentUser, reminders: [...(currentUser.reminders || []), { id: `rem_${Date.now()}`, text: content, priority: 'MEDIUM', completed: false, dueDate: new Date().toISOString() }] });
  }, [currentUser]);

  const handleDeleteMessage = useCallback((id: string) => { setMessages(prev => prev.filter(m => m.id !== id)); }, []);

  const stopCurrentVocalize = useCallback(() => {
    if (activeSourceRef.current) {
      try { activeSourceRef.current.stop(); } catch (e) {}
      activeSourceRef.current = null;
    }
    setSpeakingId(null);
    currentVocalizeIdRef.current = null;
  }, []);

  const toggleVoiceMode = useCallback(async () => {
    if (isVoiceMode) {
      setIsVoiceMode(false);
      streamRef.current?.getTracks().forEach(t => t.stop());
      inputAudioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      return;
    }
    try {
      setIsVoiceMode(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(session => session.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            const audioData = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              audioSourcesRef.current.add(source);
            }
          },
          onclose: () => setIsVoiceMode(false),
          onerror: () => setIsVoiceMode(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: currentUser?.preferences.voiceName || 'Kore' } } },
          systemInstruction: `Anora Voice Protocol. User: ${currentUser?.name}. Persona: ${currentUser?.preferences.persona}.`
        }
      });
    } catch (err) { setIsVoiceMode(false); }
  }, [isVoiceMode, currentUser]);

  const handleVocalize = async (id: string, text: string, affect: NeuralAffect = 'SOVEREIGN') => {
    if (speakingId === id) { stopCurrentVocalize(); return; }
    stopCurrentVocalize();
    setSpeakingId(id); currentVocalizeIdRef.current = id;
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      const base64 = await anoraService.speak(text, currentUser?.preferences.voiceName || 'Kore', affect);
      if (currentVocalizeIdRef.current !== id) return;
      if (!base64) throw new Error("No audio generated");
      const buffer = await decodeAudioData(decode(base64), audioCtxRef.current, 24000, 1);
      const source = audioCtxRef.current.createBufferSource();
      source.buffer = buffer; source.connect(audioCtxRef.current.destination);
      source.onended = () => { if (currentVocalizeIdRef.current === id) setSpeakingId(null); };
      activeSourceRef.current = source; source.start();
    } catch (err) { setSpeakingId(null); }
  };

  const handleFileSelect = useCallback(() => {
    fileInputRef.current?.click();
  }, []);

  const handleSend = async (text: string) => {
    const val = text.trim();
    if (!val && pendingImages.length === 0) return;

    stopCurrentVocalize();

    const chatTokenCost = Math.max(1, Math.ceil((val.length || 10) / 3));
    if (!deductTokens('chat', chatTokenCost)) return;

    if (pendingImages.length > 0) {
      if (!deductTokens('image', pendingImages.length)) return;
    }

    const intent = (t: string) => {
      const lower = t.toLowerCase();
      if (lower.includes('cad') || lower.includes('engineering')) return 'ENGINEERING';
      if (lower.includes('music') || lower.includes('lyrics')) return 'CREATIVE';
      return 'GENERAL';
    };

    const userMsg: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: val || "Neural asset shared.", 
      timestamp: new Date(), 
      images: pendingImages.length > 0 ? [...pendingImages] : undefined, 
      intent: intent(val) as any 
    };

    setMessages(prev => [...prev, userMsg]);
    setInputValue(''); 
    setPendingImages([]); 
    setIsThinking(true);

    try {
      const response = await anoraService.sendMessageWithVision(userMsg.content, userMsg.images || []);

      if (response.audioUrl) {
        if (!deductTokens('audio', 1)) {
          response.audioUrl = undefined;
        }
      }

      const anoraMsg: Message = { 
        id: (Date.now()+1).toString(), 
        role: 'anora', 
        content: response.text, 
        sources: response.sources, 
        images: response.images, 
        audioUrl: response.audioUrl,
        affect: response.affect as any, 
        timestamp: new Date() 
      };
      setMessages(prev => [...prev, anoraMsg]);
      if (currentUser?.preferences.autoRead) handleVocalize(anoraMsg.id, anoraMsg.content, anoraMsg.affect);
    } catch (err) {
      setMessages(prev => [...prev, { id: 'err', role: 'system', content: "Neural bridge unstable. Sync deferred by sovereign decree.", timestamp: new Date() }]);
    } finally { setIsThinking(false); }
  };

  if (!currentUser) return <AuthScreen onLogin={setCurrentUser} />;

  const isOwner = currentUser.role === Role.OWNER;
  const isPremium = currentUser.tier !== SubscriptionTier.FREE || isOwner;
  const accent = isOwner ? '#d4af37' : (isPremium ? '#8b5cf6' : '#3f3f46');
  const colorMode = (currentUser.preferences as any).colorMode || 'WHITE';

  return (
    <div className={`flex flex-col h-[100dvh] transition-colors duration-700 overflow-hidden ${colorMode === 'WHITE' ? 'bg-white text-zinc-800' : 'bg-zinc-900 text-white'} ${currentUser.preferences.font === 'OUTFIT' ? 'font-outfit' : 'font-inter'}`}>
      <style>{`.accent-text { color: ${accent}; } .accent-border { border-color: ${accent}20; }`}</style>
      <CommandCenter user={currentUser} isOpen={isCommandCenterOpen} onDeductToken={deductTokens} onClose={() => setIsCommandCenterOpen(false)} />
      <ProfileModal user={currentUser} isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} onUpdate={setCurrentUser} onLogout={handleLogout} />
      <AssistantFeatures user={currentUser} onUpdate={setCurrentUser} onClearHistory={handleNewThread} messagesCount={messages.length} isOpen={isHubOpen} onClose={() => setIsHubOpen(false)} />

      <header className={`flex items-center justify-between px-6 sm:px-12 pt-[calc(var(--sat)+1rem)] pb-4 border-b transition-all duration-700 ${colorMode === 'WHITE' ? 'border-zinc-100' : 'border-zinc-800'} shrink-0`}>
        <AnoraLogo size={40} color={accent} />
        <div className="flex items-center gap-4">
          <VoiceIndicator active={isVoiceMode} />
          <div className={`flex items-center gap-2 p-1 rounded-full border transition-all duration-700 ${colorMode === 'WHITE' ? 'bg-zinc-50 border-zinc-100' : 'bg-white/5 border-white/10'}`}>
            <button onClick={() => setIsHubOpen(true)} className="p-2.5 text-zinc-400 hover:text-zinc-900"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" /></svg></button>
            <button onClick={() => setIsCommandCenterOpen(true)} className="p-2.5 text-zinc-400 hover:text-zinc-900"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg></button>
            <button onClick={() => setIsProfileOpen(true)} className={`w-9 h-9 rounded-full bg-white overflow-hidden flex items-center justify-center text-[10px] font-black transition-all active:scale-90 ${isOwner ? 'ring-2 ring-amber-500 shadow-lg' : 'border border-zinc-200'}`}>
              {currentUser.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" /> : currentUser.name.charAt(0)}
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col relative overflow-hidden">
        <MessageList messages={messages} isThinking={isThinking} ownerName={currentUser.name} isOwnerView={isOwner} userTier={currentUser.tier} onVocalize={handleVocalize} onDeleteMessage={handleDeleteMessage} onSaveToMemory={handleSaveToMemory} onSaveToReminders={handleSaveToReminders} speakingId={speakingId} />
        <NeuralOrb active={isThinking} affect={activeAffect} speaking={speakingId !== null} listening={isVoiceMode} color={accent} />
      </main>

      <footer className={`px-6 sm:px-12 pb-[calc(var(--sab)+1.5rem)] pt-4 border-t shrink-0 backdrop-blur-3xl transition-all duration-700 ${colorMode === 'WHITE' ? 'bg-white/80 border-zinc-100' : 'bg-zinc-900/80 border-zinc-800'}`}>
        <div className="max-w-4xl mx-auto space-y-4">
          {pendingImages.length > 0 && (
            <div className="flex gap-3 overflow-x-auto no-scrollbar py-2 px-1 animate-in slide-in-from-bottom-2 duration-300">
               {pendingImages.map((img, idx) => (
                 <div key={idx} className="relative w-16 h-16 rounded-2xl overflow-hidden border border-zinc-100 shadow-md shrink-0 group">
                    <img src={img} className="w-full h-full object-cover" />
                    <button onClick={() => setPendingImages(prev => prev.filter((_, i) => i !== idx))} className="absolute top-1 right-1 p-1 bg-black/60 text-white rounded-full backdrop-blur-sm opacity-100 transition-opacity">
                      <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                 </div>
               ))}
            </div>
          )}
          <div className="flex items-center gap-4">
            <button onClick={handleFileSelect} className={`p-4 rounded-2xl border transition-all active:scale-95 ${isPremium ? 'text-zinc-400 hover:text-zinc-900' : 'text-zinc-200 opacity-50'} ${colorMode === 'WHITE' ? 'bg-zinc-50 border-zinc-100' : 'bg-white/5 border-white/10'}`}>
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
              <input type="file" ref={fileInputRef} hidden multiple accept="image/*" onChange={e => { 
                  const files = e.currentTarget.files; 
                  if (files) (Array.from(files) as File[]).forEach(f => { 
                    const reader = new FileReader(); 
                    reader.onload = ev => setPendingImages(p => [...p, ev.target?.result as string]); 
                    reader.readAsDataURL(f); 
                  }); 
                  e.target.value = '';
                }} />
            </button>
            <div className="flex-1 relative flex items-center">
              <input 
                type="text" 
                value={inputValue} 
                onChange={e => setInputValue(e.target.value)} 
                onKeyDown={e => e.key === 'Enter' && handleSend(inputValue)} 
                placeholder={isOwner ? "Sovereign Command..." : "Neural Sync..."} 
                className={`w-full border rounded-[2rem] pl-6 pr-16 py-4.5 outline-none transition-all focus:ring-1 focus:ring-black/5 ${colorMode === 'WHITE' ? 'bg-zinc-50 border-zinc-100 text-zinc-900' : 'bg-white/5 border-white/10 text-white focus:bg-white/10'}`} 
              />
              <button onClick={() => handleSend(inputValue)} className={`absolute right-1.5 p-3.5 rounded-full transition-all active:scale-90 ${isOwner ? 'bg-amber-500' : 'bg-zinc-900'} text-white shadow-lg`}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7m0 0l-7 7m7-7H3" /></svg></button>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { User, Role, SubscriptionTier, CustomTier, Reminder, TierCapability, UpgradeRequest, NeuralMemoryItem, SiteLog, LyricDraft, VaultItem, Thread, Persona } from '../types';
import { LANGUAGES } from '../constants';
import { anoraService } from '../services/geminiService';

interface AssistantFeaturesProps {
  user: User;
  onUpdate: (user: User) => void;
  onClearHistory: () => void;
  messagesCount: number;
  isOpen: boolean;
  onClose: () => void;
}

const PLAN_FEATURES = {
  FREE: [
    "20,000 Daily Synapse Tokens",
    "Balanced Intelligence Core",
    "Standard Personas",
    "Watermarked Image Synthesis",
    "Basic Timeline & Projects"
  ],
  PRO: [
    "100,000 Daily Synapse Tokens",
    "Deep Reasoning Core (Gemini Pro)",
    "Google Search & Maps Grounding",
    "100 High-Res Images (No Watermark)",
    "20 Cinematic Videos (Veo 3.1)",
    "Direct Audio Manifestation (Voice Replies)",
    "RHB Engineering Site Logs",
    "Creative Lyric Studio",
    "Encrypted Neural Vault",
    "Advanced Neural Analytics"
  ],
  LIFETIME: [
    "Infinite Synapse Tokens",
    "Priority Sovereign Compute",
    "All Pro Protocols Included",
    "Direct Audio Manifestation (Voice Replies)",
    "Permanent Neural Bond",
    "Custom AI Mood Synthesizer",
    "Early Access to Neural v9.0"
  ]
};

export const AssistantFeatures: React.FC<AssistantFeaturesProps> = ({ user, onUpdate, onClearHistory, messagesCount, isOpen, onClose }) => {
  const [tab, setTab] = useState<'ANALYTICS' | 'ARCHIVES' | 'NEURAL_MEMORY' | 'TIMELINE' | 'PROJECTS' | 'SITE_LOGS' | 'LYRIC_STUDIO' | 'VAULT' | 'PROTOCOLS' | 'UPGRADE' | 'USERS' | 'REQUESTS'>('ANALYTICS');
  const [newItem, setNewItem] = useState('');
  const [newDesc, setNewDesc] = useState('');

  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [upgradeRequests, setUpgradeRequests] = useState<UpgradeRequest[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  const [requestedTier, setRequestedTier] = useState<SubscriptionTier>(SubscriptionTier.PRO);
  const [upgradeMessage, setUpgradeMessage] = useState('');
  const [isRequesting, setIsRequesting] = useState(false);

  // Payment states
  const [paymentMode, setPaymentMode] = useState<'REQUEST' | 'PAY'>('PAY');
  const [paymentPhase, setPaymentPhase] = useState<'SELECT' | 'PAY_PORTAL' | 'VERIFY'>('SELECT');
  const [selectedPlanPrice, setSelectedPlanPrice] = useState<number>(0);
  const [isVerifyingPayment, setIsVerifyingPayment] = useState(false);
  const [paymentConfirmed, setPaymentConfirmed] = useState(false);
  const [screenshot, setScreenshot] = useState<string | null>(null);
  const [verificationError, setVerificationError] = useState<string | null>(null);
  const [showPlanDetails, setShowPlanDetails] = useState<SubscriptionTier | null>(null);

  const screenshotInputRef = useRef<HTMLInputElement>(null);

  const refreshData = () => {
    const usersData = localStorage.getItem('anora_users_db');
    if (usersData) setAllUsers(JSON.parse(usersData));
    const reqData = localStorage.getItem('anora_upgrade_requests');
    if (reqData) setUpgradeRequests(JSON.parse(reqData));
  };

  useEffect(() => {
    if (isOpen) {
      refreshData();
      setScreenshot(null);
      setVerificationError(null);
    }
  }, [isOpen]);

  const handleScreenshotUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => setScreenshot(ev.target?.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleRequestUpgrade = () => {
    if (!upgradeMessage.trim()) {
      alert("Please provide a justification for elevation.");
      return;
    }
    setIsRequesting(true);

    const request: UpgradeRequest = {
      id: `req_${Date.now()}`,
      userId: user.id,
      userName: user.name,
      userEmail: user.email,
      requestedTier: requestedTier,
      message: upgradeMessage,
      timestamp: new Date().toISOString(),
      status: 'PENDING'
    };

    const existing = JSON.parse(localStorage.getItem('anora_upgrade_requests') || '[]');
    localStorage.setItem('anora_upgrade_requests', JSON.stringify([...existing, request]));

    setTimeout(() => {
      setIsRequesting(false);
      setUpgradeMessage('');
      alert("Neural elevation request transmitted to the Sovereign.");
      refreshData();
      setPaymentMode('PAY'); 
    }, 1500);
  };

  const initiatePayment = (tier: SubscriptionTier, price: number) => {
    setRequestedTier(tier);
    setSelectedPlanPrice(price);
    setPaymentPhase('PAY_PORTAL');

    const upiId = "8233538355@ybl";
    const name = "Anora Sovereign";
    const upiLink = `upi://pay?pa=${upiId}&pn=${encodeURIComponent(name)}&am=${price}&cu=INR&tn=Anora%20Neural%20Upgrade`;

    window.location.href = upiLink;
  };

  const handleConfirmActivation = async () => {
    if (!screenshot) {
      alert("Payment receipt screenshot is required for activation.");
      return;
    }

    setPaymentPhase('VERIFY');
    setIsVerifyingPayment(true);
    setVerificationError(null);

    try {
      const result = await anoraService.verifyPaymentScreenshot(screenshot, selectedPlanPrice);

      if (result.verified) {
        const users: User[] = JSON.parse(localStorage.getItem('anora_users_db') || '[]');
        const uIdx = users.findIndex(u => u.id === user.id);

        const updatedUser = { 
          ...user, 
          tier: requestedTier, 
          role: requestedTier === SubscriptionTier.PRO || requestedTier === SubscriptionTier.LIFETIME ? Role.PREMIUM : user.role 
        };

        if (uIdx !== -1) {
          users[uIdx] = updatedUser;
          localStorage.setItem('anora_users_db', JSON.stringify(users));
        }

        onUpdate(updatedUser);
        setIsVerifyingPayment(false);
        setPaymentConfirmed(true);

        setTimeout(() => {
          setPaymentConfirmed(false);
          setPaymentPhase('SELECT');
          setScreenshot(null);
          alert(`Neural Link Ascended to ${requestedTier}. Welcome to the Sovereign Core.`);
        }, 1500);
      } else {
        setIsVerifyingPayment(false);
        setVerificationError(result.reason || "Payment criteria not fulfilled. Verification declined.");
      }
    } catch (err) {
      console.error("Verification error:", err);
      setIsVerifyingPayment(false);
      setVerificationError("Neural bridge failed to analyze the asset. Please try again with a clear screenshot.");
    }
  };

  const handleActionRequest = (requestId: string, approve: boolean) => {
    const requests: UpgradeRequest[] = JSON.parse(localStorage.getItem('anora_upgrade_requests') || '[]');
    const reqIndex = requests.findIndex(r => r.id === requestId);
    if (reqIndex === -1) return;

    const request = requests[reqIndex];
    if (approve) {
      const users: User[] = JSON.parse(localStorage.getItem('anora_users_db') || '[]');
      const uIndex = users.findIndex(u => u.id === request.userId);
      if (uIndex !== -1) {
        users[uIndex].tier = request.requestedTier;
        if (users[uIndex].role === Role.USER) users[uIndex].role = Role.PREMIUM;
        localStorage.setItem('anora_users_db', JSON.stringify(users));
        setAllUsers(users);
        window.dispatchEvent(new Event('anora_database_updated'));
      }
    }

    requests[reqIndex].status = approve ? 'APPROVED' : 'DENIED';
    localStorage.setItem('anora_upgrade_requests', JSON.stringify(requests));
    refreshData();
  };

  const addItem = () => {
    if (!newItem.trim()) return;
    const updated = { ...user };

    if (tab === 'TIMELINE') {
      updated.reminders.push({ id: Date.now().toString(), text: newItem, priority: 'MEDIUM', completed: false, dueDate: new Date().toISOString() });
    } else if (tab === 'PROJECTS') {
      updated.projects.push({ id: Date.now().toString(), name: newItem, description: newDesc, status: 'ACTIVE' });
    } else if (tab === 'SITE_LOGS') {
      if (!updated.siteLogs) updated.siteLogs = [];
      updated.siteLogs.push({ id: Date.now().toString(), project: newItem, date: new Date().toISOString(), details: newDesc, status: 'PENDING' });
    } else if (tab === 'LYRIC_STUDIO') {
      if (!updated.lyrics) updated.lyrics = [];
      updated.lyrics.push({ id: Date.now().toString(), title: newItem, genre: 'GENERAL', content: newDesc, timestamp: new Date().toISOString() });
    } else if (tab === 'VAULT') {
      if (!updated.vault) updated.vault = [];
      updated.vault.push({ id: Date.now().toString(), title: newItem, content: newDesc, type: 'TEXT' });
    }

    onUpdate(updated);
    setNewItem('');
    setNewDesc('');
  };

  const removeItem = (id: string, list: string) => {
    const updated = { ...user };
    if (list === 'projects') updated.projects = updated.projects.filter(i => i.id !== id);
    if (list === 'reminders') updated.reminders = updated.reminders.filter(i => i.id !== id);
    if (list === 'memory') updated.memory = (updated.memory || []).filter(i => i.id !== id);
    if (list === 'siteLogs') updated.siteLogs = (updated.siteLogs || []).filter(i => i.id !== id);
    if (list === 'lyrics') updated.lyrics = (updated.lyrics || []).filter(i => i.id !== id);
    if (list === 'vault') updated.vault = (updated.vault || []).filter(i => i.id !== id);
    if (list === 'threads') updated.threads = (updated.threads || []).filter(i => i.id !== id);
    onUpdate(updated);
  };

  const archiveCurrentThread = () => {
    const persona = user.preferences.persona || 'DEFAULT';
    const activeKey = `anora_history_${user.email}_${persona}`;
    const rawHistory = localStorage.getItem(activeKey);

    if (!rawHistory) return;
    const history = JSON.parse(rawHistory);
    if (history.length <= 1) return; // Only archive if there's interaction

    const threadId = `thread_${Date.now()}`;
    const lastMsg = history[history.length - 1];

    const newThread: Thread = {
      id: threadId,
      persona: persona,
      title: `${persona} Session - ${new Date().toLocaleDateString()}`,
      timestamp: new Date().toISOString(),
      lastSnippet: lastMsg.content.substring(0, 60) + '...'
    };

    // Save history to archive key
    localStorage.setItem(`anora_archive_${threadId}`, rawHistory);

    // Update user threads
    const updatedUser = { ...user, threads: [newThread, ...(user.threads || [])] };
    onUpdate(updatedUser);

    // Clear active history and trigger new thread
    localStorage.removeItem(activeKey);
    onClearHistory();
  };

  const resumeArchivedThread = (thread: Thread) => {
    const persona = user.preferences.persona || 'DEFAULT';
    const activeKey = `anora_history_${user.email}_${persona}`;
    const archiveKey = `anora_archive_${thread.id}`;

    const archivedHistory = localStorage.getItem(archiveKey);
