          id: currentThreadId,
          persona: persona,
          title: `${persona} Auto-Archive - ${new Date().toLocaleDateString()}`,
          timestamp: new Date().toISOString(),
          lastSnippet: lastMsg.content.substring(0, 60) + '...'
